"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["30178"],{20427(e,t,n){n.d(t,{Ay:()=>o,RM:()=>r});var i=n(74848),s=n(28453);let r=[];function a(e){let t={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"on-appreciating-classical-poetry-through-ch\xe1n-zh\u014Dng-shu\u014D-ch\xe1ns-regulated-verses-tiger-hill--mount-tai",children:'On Appreciating Classical Poetry Through Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n\u2019s Regulated Verses "Tiger Hill" / "Mount Tai"'})}),"\n",(0,i.jsxs)(t.blockquote,{children:["\n",(0,i.jsx)(t.p,{children:"2006/7/27 17:21:08"}),"\n"]}),"\n",(0,i.jsx)(t.p,{children:'Classical poetry is certainly not something only the ancients could write \u2014 people today can write it just the same. Moreover, the artistic energy of classical poetry as a form has absolutely not been exhausted. One can declare with certainty that, due to the corrupted genes of modern vernacular Chinese imported from the West and Japan, modern Chinese vernacular poetry \u2014 beyond repeating things the West and Japan have already worn out \u2014 is basically nothing more than a self-indulgent game played within a small circle. The Chinese genes of classical poetry, however, ensure that after some effort, it will inevitably remain the most quintessentially Chinese form of poetry. Due to the impact of the May Fourth Movement and other garbage movements even more May Fourth than May Fourth itself, the appreciation of classical poetry has become very unfamiliar to the vast majority of people. Here, this ID will discuss this topic through the seven-character regulated verses "Tiger Hill" and "Mount Tai." These two regulated verses are only mediocre among what this ID has written. As mentioned before, anything above average cannot be posted online \u2014 plagiarism is too rampant nowadays, so only scraps can be put up. Both of these have been posted before, so I\u2019ll just grab them as demonstration frogs for dissection. First, "Tiger Hill":'}),"\n",(0,i.jsxs)("div",{style:{fontWeight:"normal",textAlign:"center"},children:[(0,i.jsx)(t.p,{children:"Tiger Hill (Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n)"}),(0,i.jsxs)(t.p,{children:["Beneath Tiger Hill, the tomb of Wu\u2019s king",(0,i.jsx)("br",{}),"\nAncient trees, verdant green, buzzing summer cicadas",(0,i.jsx)("br",{}),"\nGreen grass, long steps, lonely clouds above",(0,i.jsx)("br",{}),"\nGray walls, tilting tower, somber and bleak",(0,i.jsx)("br",{}),"\nThree thousand swords buried in barren earth",(0,i.jsx)("br",{}),"\nHalf a century\u2019s ambition turned to raging tides",(0,i.jsx)("br",{}),"\nBlood not yet dry on the blade in a fish\u2019s belly",(0,i.jsx)("br",{}),"\nOn the silk-washing stream, songs of Yue entice"]})]}),"\n",(0,i.jsx)(t.p,{children:"\u201CBeneath Tiger Hill, the tomb of Wu\u2019s king\u201D opens plainly, not aspiring to the dramatic entrance typical of seven-character regulated verse openings. This is mainly determined by the overall conception of the work. The first four lines depict a very real scene, and reality is always mundane. No matter how impressive the history, in the end it amounts to nothing more than a name like \u201CBeneath Tiger Hill, the tomb of Wu\u2019s king.\u201D This plain opening is precisely the most realistic and the most historical. Although this ID never appears in the entire poem, it was of course written from this ID\u2019s travels, observations, and reflections \u2014 this ID is present at every moment within it. This ID\u2019s framing and phrasing in fact reflect this ID\u2019s viewpoint, but this viewpoint need not be written out explicitly. Even in Tang poetry, lines of direct satirical commentary like \u201CLiu Bang and Xiang Yu never bothered with books\u201D are not to this ID\u2019s liking. As for Song poetry, even when wrapped in many complex terms, it is even more exposed. This ID naturally prefers to let everything remain unspoken \u2014 not even the most subtly worded direct commentary is wanted. What is sought is pure depiction and narration. But a person\u2019s observation is always individual, naturally carrying a personal perspective. A zero-degree angle is often the widest angle of all."}),"\n",(0,i.jsx)(t.p,{children:"Everything starts from the most ordinary \u201CBeneath Tiger Hill, the tomb of Wu\u2019s king.\u201D First, of course, one hears about it, then one goes. What one arrives at is simply \u201CBeneath Tiger Hill, the tomb of Wu\u2019s king,\u201D and all understanding of it can only and must begin from this \u201CBeneath Tiger Hill, the tomb of Wu\u2019s king.\u201D The second line, \u201CAncient trees, verdant green, buzzing summer cicadas\u201D \u2014 upon arriving at the scene, a person\u2019s most sensitive faculty is usually hearing. First one hears the cicadas calling; the season is also established \u2014 summer. Then one sees many ancient trees. Why \u201Cverdant green\u201D? It is the feeling of Handel\u2019s famous aria \u201COmbra mai fu\u201D (\u201CVerdant Canopy\u201D) \u2014 that aria is sung by a king and does not connote desolation. As for whether the cicadas are actually in the trees, of course one cannot see them; it is merely inference, assumption, yet it was the most immediate sensation upon first arriving. The verse omits many things, but these things can be filled in to varying degrees through individual experience."}),"\n",(0,i.jsx)(t.p,{children:"The chin couplet, \u201CGreen grass, long steps, lonely clouds above / Gray walls, tilting tower, somber and bleak,\u201D is a direct description of what is seen. \u201CGreen grass, long steps, lonely clouds above\u201D moves from low to high, which is also what a person most naturally perceives while walking upward. The green grass and long steps ascend together, then one\u2019s gaze naturally extends upward to the sky. There are not many clouds, and viewed along the angle of the long steps, the clouds hang above with nothing to cling to \u2014 unlike the steps that have green grass beside them \u2014 very lonely. \u201CGreen grass\u201D in Chinese linguistic context carries many connotations, such as \u201CSpring grass green year after year, will the wanderer ever return?\u201D The long steps are the path by which later generations come to view the site, yet the grass has already turned green while the princes have long turned to dust. The clouds hang lonely above \u2014 that patch of cloud, too, carries many meanings in the Chinese linguistic context. The unified yet divergent implications of \u201CGreen grass, long steps, lonely clouds above\u201D are far richer than the literal meaning \u2014 take your time to savor it. As for \u201CGray walls, tilting tower, somber and bleak,\u201D it is purely direct description. \u201CSomber and bleak\u201D is the pure sensation of \u201Cgray walls, tilting tower,\u201D without any great deeper meaning. In this way, the upper line is rich in meaning and ethereal, while the lower line is very solid and simple, together forming the contrapuntal whole of this couplet. Some imitators of the Xikun style try to cram riddles into every line, which first creates imbalance and actually becomes monotonous. Furthermore, poetry is meant to express emotion, not to review allusions \u2014 this point is extremely important."}),"\n",(0,i.jsx)(t.p,{children:"The last four lines \u2014 \u201CThree thousand swords buried in barren earth / Half a century\u2019s ambition turned to raging tides / Blood not yet dry on the blade in a fish\u2019s belly / On the silk-washing stream, songs of Yue entice\u201D \u2014 return from reality to history, with the transition stemming entirely from \u201Csomber and bleak.\u201D Why \u201Csomber and bleak\u201D? Because the \u201Cgray walls, tilting tower\u201D and the reality described in the first four lines all carry so-called history, and therefore a so-called sense of history. Additionally, this intangible aura of history naturally draws one into a hazy, illusory historical space. The last four lines are still plain depiction, but what they depict is a kind of history \u2014 or rather, historical legends and historical impressions. The allusions within are well known to all: each line writes about one person, and the four most important figures in the story of the Kingdom of Wu are all present. As for which four and how they correspond, those who know will understand at a glance, and those who don\u2019t should go back and read \u2014 that is better than this ID spelling it out directly."}),"\n",(0,i.jsx)(t.p,{children:"This technique of parallel enumeration across four lines is not uncommon in classical seven-character regulated verses. There are even cases of seven parallel lines with only the last line providing closure. But having four parallel lines at the end without any closure is extremely rare in classical regulated verses \u2014 whether it absolutely never occurred, I cannot guarantee, but at least this ID has never seen it. It is somewhat like ending with an unresolved dissonant chord in music. But the singing in \u201COn the silk-washing stream, songs of Yue entice\u201D and the aura of \u201Csomber and bleak\u201D are both intangible yet seemingly perceptible things that can traverse history and reality. Here, the non-resolution paradoxically feels resolved, so the arrangement of this line is not arbitrary \u2014 there are many subtleties within, which you can slowly discover for yourselves."}),"\n",(0,i.jsx)(t.p,{children:"Here, only the most critical points in history are written out; the rest is naturally filled in by the reader. There is no commentary here, yet commentary is embedded within it. The historical tragedies, comedies, and dramas, in the contrast of these four lines, are profoundly thought-provoking. It is precisely this history that gives us \u201CBeneath Tiger Hill, the tomb of Wu\u2019s king\u201D and that gave this ID the occasion to visit. Therefore, the open-ended structure of the last four lines naturally circles back to the first line. This also corresponds well to the actual experience of ordinary people: we visit a site, carry away a fragment of historical memory, but this memory is so illusory that no conclusion can be drawn \u2014 only stories and legends, interpreted by each person according to their own thinking, or simply forgotten. What conclusion could there possibly be? Yet this ID\u2019s viewpoint is in fact conveyed within it, along with infinite sentiments and warnings. As for the flavors therein, I leave them for each of you to understand on your own!"}),"\n",(0,i.jsx)(t.p,{children:'Second, "Mount Tai":'}),"\n",(0,i.jsxs)("div",{style:{fontWeight:"normal",textAlign:"center"},children:[(0,i.jsx)(t.p,{children:"Mount Tai (Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n)"}),(0,i.jsxs)(t.p,{children:["Mount Tai stands towering, dividing Qi and Lu",(0,i.jsx)("br",{}),"\nBlocking sky, splitting plains, the sea lies to the east",(0,i.jsx)("br",{}),"\nForests trace dawn to dusk, ridges and cliffs break off",(0,i.jsx)("br",{}),"\nMountain forms in shade and sun, trees and grass merge",(0,i.jsx)("br",{}),"\nSilent coiling clouds seem about to bring rain",(0,i.jsx)("br",{}),"\nGracefully passing the sun, suddenly becoming wind",(0,i.jsx)("br",{}),"\nFading sunset shadows brush the First Emperor\u2019s stone",(0,i.jsx)("br",{}),"\nIn ages past, they witnessed Emperor Wu\u2019s grandeur"]})]}),"\n",(0,i.jsx)(t.p,{children:"Though this, like the previous one, is about a visit where this ID does not appear yet is present at every moment, the approach is very different. The first four lines describe the overall impression of Mount Tai from various angles \u2014 far and near, high and low \u2014 while the details are arranged according to the continuously elevating altitude of the ascent. I won\u2019t go into specifics. \u201CSilent coiling clouds seem about to bring rain\u201D marks a turn, but unlike the dramatic shift above, it merely turns to the boundary between reality and history. The wind and clouds of history blend with those before one\u2019s eyes \u2014 and \u201Cbefore one\u2019s eyes\u201D does not necessarily refer exclusively to this ID\u2019s perspective; it could also be what Mount Tai itself has witnessed. The poem\u2019s greatest force, through this blending of history and reality, converges entirely upon the final couplet."}),"\n",(0,i.jsx)(t.p,{children:"\u201CFading sunset shadows brush the First Emperor\u2019s stone / In ages past, they witnessed Emperor Wu\u2019s grandeur\u201D \u2014 there are many layers of meaning here. For example: First, a sentiment akin to \u201Cwestern wind, lingering sunset, the palaces and towers of the Han dynasty.\u201D Second, Emperor Wu of Han once viewed the relics of the First Emperor of Qin; today we come to look as well, and at the same time we view Emperor Wu\u2019s relics too \u2014 and \u201Cwho will come after us, mourning in vain that those before us once existed?\u201D What do we have that will be worth viewing for later generations? Third, the fading sunset has watched not only the First Emperor and Emperor Wu, but also watches us. The sunset sweeps through history and also sweeps before our eyes in the present moment \u2014 history and reality, everything sweeps past like shadows. Fourth, even the mighty achievements of the First Emperor and Emperor Wu have turned to fading shadows, ultimately standing beneath the dying sunset. Mount Tai endures \u2014 who is the Mount Tai of reality and history? And from an even higher vantage point, the Mount Tai of reality and history is not eternal either \u2014 so where does eternity lie? There are still other, subtler meanings \u2014 take your time to ponder them."})]})}function o(e={}){let{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(a,{...e})}):a(e)}},65504(e,t,n){n.r(t),n.d(t,{metadata:()=>i,default:()=>u,frontMatter:()=>o,contentTitle:()=>l,toc:()=>d,assets:()=>h});var i=JSON.parse('{"id":"poems/poemappreciation","title":"","description":"","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/poems/poemappreciation.md","sourceDirName":"poems","slug":"/poems/poemappreciation","permalink":"/en/poems/poemappreciation","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"poemappreciation","title":"","hide_table_of_contents":true,"sidebar_label":"On Appreciating Classical Poetry Through Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n\'s Seven-Character Regulated Verses \\"Tiger Hill\\"/\\"Mount Tai\\" (2006/7/27 17:21:08)"},"sidebar":"poemsSidebar","previous":{"title":"Regulated Verse: A Business Trip to Nanchang Coinciding with Mid-Autumn Festival (2006/7/5 21:14:59)","permalink":"/en/poems/midautumn"},"next":{"title":"Two Vernacular Poems: October / Humanity Accustomed to Masturbation (2006/8/13 17:48:00)","permalink":"/en/poems/2vernacularpoetry"}}'),s=n(74848),r=n(28453),a=n(20427);let o={id:"poemappreciation",title:"",hide_table_of_contents:!0,sidebar_label:'On Appreciating Classical Poetry Through Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n\'s Seven-Character Regulated Verses "Tiger Hill"/"Mount Tai" (2006/7/27 17:21:08)'},l,h={},d=[...a.RM];function c(e){return(0,s.jsx)(a.Ay,{})}function u(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(c,{...e})}):c(e)}},28453(e,t,n){n.d(t,{R:()=>a,x:()=>o});var i=n(96540);let s={},r=i.createContext(s);function a(e){let t=i.useContext(r);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:a(e.components),i.createElement(r.Provider,{value:t},e.children)}}}]);